"""Frame the retained experiments around conditional feedback failure boundaries.

Editorial reanalysis only: no new experiment, threshold estimate or protocol change.
"""
import json
from pathlib import Path
from copy import deepcopy

TITLE = 'Failure Boundaries of Censored Passive Feedback in Authenticated Wireless Sensor Routing'
ABSTRACT = ('Censoring missing forwarding evidence avoids treating every unobserved transmission as malicious, but it also removes a route for revising earlier positive evidence. We benchmark this trade-off using active-proof, naive-passive, frozen-prior and capacity-matched routing controls. In 750 IEEE 802.15.4 runs on thirty new fixtures, ACK-gated censored feedback raises blackhole delivery from 71.28% to 75.94% relative to active proofs, a paired gain of 4.67 percentage points (95% interval 2.36–6.97; Holm-adjusted p=0.0161). This conditional gain does not establish a unique censoring or attention advantage. A separate 600-run Cooja transfer experiment exposes a failure after a previously cooperative relay begins dropping traffic: with scheduled processing delays, censored feedback delivers 32.94% and active proofs 79.11%. Enabling proof generation while retaining censored evidence delivers 32.83%, indicating that proof generation alone does not restore delivery in this setting. These experiments use different implementations and cannot isolate behavior change as the sole cause of their contrasting outcomes. Separate authenticated transfer and factorial studies retain the absence of demonstrated attention superiority and a proof-traffic penalty under always-on listening. Fixed-point MCU emulation improves execution, but signed-receipt deadline misses remain 68/200. The contribution is a reproducible characterization of conditional feedback performance and an exposed adaptation limitation, rather than a universally preferable routing mechanism. Fixed geometry, heuristic risk scores, scheduled processing delays and unmeasured physical RF and energy restrict deployment inference.')

REPLACEMENTS = [
('1.1 Benchmark contribution', '1.1 Feedback performance and failure boundaries'),
('We benchmark ACK-gated censored passive feedback against active proofs while retaining controls for missing-evidence penalties, evidence updating and policy capacity.', 'The benchmark examines when suppressing negative updates from missing evidence helps delivery and when it leaves a routing policy unable to revise earlier favorable evidence. ACK-gated censored passive feedback is compared with active proofs, naive passive feedback, frozen priors and capacity-matched policies.'),
('The prespecified decision combines a blackhole delivery comparison against active proofs with delivery, critical-service and energy-efficiency margins against frozen-prior attention. Naive-passive and capacity-matched controls assess whether the outcome can be attributed specifically to censoring or policy architecture. An improvement over active proofs alone cannot establish either attribution.', 'The original prespecified decision combines a blackhole delivery comparison against active proofs with delivery, critical-service and energy-efficiency margins against frozen-prior attention. Its conditional gain is retained alongside the separate Cooja transfer failure in Section 5.9. The contributions are the controlled feedback comparison, an exposed limitation in adaptation after relay behavior changes, and a traceable separation of policy transfer from emulated execution. None establishes a new learning algorithm, a unique censoring advantage or a deployment guarantee.'),
('A second implementation stage examines whether the frozen policies can use authenticated messages and node-local transit records. It comprises 180 new radio runs and separate serial-interface and firmware-emulation checks. Sections 2–4 report the feedback benchmark; Section 5 describes the authenticated transport and evaluates it separately. Its changed observation model prevents carrying the earlier performance claim into this branch.', 'A separate implementation stage evaluates frozen policies using authenticated messages and node-local transit records in 180 radio runs, followed by serial-interface, firmware-emulation and Cooja checks. Sections 2–4 retain the original feedback benchmark; Section 5 evaluates the changed transport and execution conditions. Section 6 connects the conditional gain and transfer failure without pooling their outcomes or treating their different observation models as an isolated causal contrast.'),
('5.9 Cooja feedback and policy transfer', '5.9 Cooja transfer and relay behavior change'),
('The original 750-run benchmark supports replacing the tested active-proof mechanism within its prespecified margins. Because eligibility and expiry rules change together with control traffic, the observed difference cannot be assigned to proof airtime alone. Comparisons with naive passive and frozen prior do not establish a unique censoring effect after correction. Retaining the earlier unsuccessful architecture comparisons prevents the feedback result from being recast as evidence for neural-policy superiority.', 'The evidence supports a conditional feedback comparison. Censored feedback meets the original 750-run decision rule, yet loses substantially to active proofs in the separate delayed Cooja blackhole setting. These studies differ in topology, traffic, state construction and execution, so their contrast does not identify behavior change as the sole cause. Within Cooja, the censored-plus-proof control tests whether enabling proof generation under the retained censored rule restores delivery; it does not. Eligibility and expiry semantics still differ between active and censored arms, preventing attribution of the full gap to one update rule.'),
('6.2 Future experiments', '6.3 Future experiments'),
('ACK-gated censored passive feedback improves blackhole delivery over active proofs by 4.67 percentage points in the prespecified thirty-fixture benchmark. Matched controls establish neither a unique censoring effect nor neural-policy superiority. The separate 180-run authenticated transfer study likewise shows no established attention advantage, while the 240-run factorial extension identifies a proof-traffic penalty under always-on listening. These findings apply to the declared feedback, traffic and radio models.', 'The benchmark identifies a conditional benefit and a consequential transfer failure. ACK-gated censored passive feedback improves blackhole delivery over active proofs by 4.67 percentage points in the original thirty-fixture study, but delivers 32.94% against 79.11% for active proofs in the separate delayed Cooja behavior-change setting. Matched controls establish neither a unique censoring advantage nor neural-policy superiority. These outcomes delimit the tested mechanisms; they do not locate a universal switching threshold between passive and active feedback.'),
('Behavior change exposes a different boundary. In the 600-run Cooja delayed condition, active proofs deliver 79.11%, censored feedback 32.94% and naive feedback 54.89%; censored feedback with proof generation enabled delivers 32.83%. Censoring alone cannot reduce earlier positive trust when later observations disappear. Fixed-point MCU execution and fast private receipts improve narrower execution paths, but the original 90 ms signed-receipt target remains unmet. Physical RF, measured energy, production key storage and deployment performance remain unvalidated.', 'Censored feedback with proof generation enabled delivers 32.83% in that Cooja condition, while naive feedback delivers 54.89%. Keeping effective failure counts fixed prevents missing observations alone from reversing prior positive evidence; other routing inputs can still alter actions. This mechanism-level limitation and the retained negative outcomes define the benchmarking contribution. Fixed-point MCU execution and fast private receipts improve narrower paths, but signed-receipt deadline misses remain 68/200 and the original 90 ms target is unmet. Physical RF, measured energy, production key storage and deployment performance remain unvalidated.')]
BOUNDARY = [
'6.2 Interpretation of the exposed failure boundary',
'With the rate-anomaly term disabled, censored feedback keeps the effective failure count β at 1 and never decreases the effective success count α. If no new accepted evidence arrives, these counts and their derived risk coordinates remain unchanged. Positive observations can increase α, but subsequent silence supplies no corrective count. This follows from Eqs. (3)–(5); it is a property of the declared estimator, not evidence that every learned routing action must remain fixed. Cache freshness, link estimates, geometry and service debt can still change the selected relay.',
'Table 11 and Fig. 12 expose the practical consequence in the tested four-node transfer setting. The delayed active-minus-censored delivery contrast is +46.17 percentage points (95% paired interval +36.89 to +54.50; Holm-adjusted p=0.00016). Adding proof generation to censored feedback changes delivery by −0.11 percentage points (95% paired interval −0.50 to +0.39; Holm-adjusted p=1). The second contrast supplies no evidence of recovery from proof generation alone; its nonsignificance is not a population-equivalence result. Active-proof semantics include different eligibility and expiry rules, so the contrast does not isolate the effect of negative updates.',
'The benchmark exposes a failure condition rather than estimating its onset. Attack onset, warm-up duration, channel quality, geometry and checkpoint are not swept independently. A universal change-point, a safe passive-feedback operating region and the cost-optimal moment to request a proof therefore remain unidentified. The current paper reports that boundary honestly; an adaptive probing policy would be a new mechanism requiring a separately frozen evaluation.'
]

def transform_text(text):
    if text.startswith('Missing forwarding evidence can reflect packet loss'): return ABSTRACT
    for before, after in REPLACEMENTS:
        text = text.replace(before, after)
    return text

def apply(doc, root):
    out = Path(root) / 'publication/array'
    abstract = doc.paragraphs[next(i for i,p in enumerate(doc.paragraphs) if p.text == 'Abstract')+1]
    edits = []
    for p in doc.paragraphs:
        old = p.text
        if p.style.name == 'Title': new = TITLE
        elif p is abstract: new = ABSTRACT
        elif p._p is abstract._p: new = ABSTRACT
        else: new = transform_text(old)
        if new != old:
            p.text = new
            edits.append({'before': old, 'after': new})
    anchor = next(p for p in doc.paragraphs if p.text == '6.3 Future experiments')
    body = next(p for p in doc.paragraphs if p.text.startswith('The simulated network has'))
    for index, text in enumerate(BOUNDARY):
        p = anchor.insert_paragraph_before(text, 'Heading 2' if index == 0 else None)
        if index:
            if p._p.pPr is not None: p._p.remove(p._p.pPr)
            if body._p.pPr is not None: p._p.insert(0, deepcopy(body._p.pPr))
    assert len(ABSTRACT.split()) <= 250
    (out/'failure_boundary_edits.json').write_text(json.dumps({'classification':'Editorial interpretation of retained outcomes; no new experiments or threshold estimation','replacements':edits,'added_paragraphs':BOUNDARY}, indent=2, ensure_ascii=False)+'\n')
    return {'failure_boundary_revision': True, 'abstract_words':len(ABSTRACT.split())}
